 /// <summary>Street dressing a section generated (mailboxes, bins, yard props) gives way to a shared building: the items on its squares and
 /// its one-square margin are taken out and returned so a failed placement can put them back.</summary>
 static List<(MapProject,WorldDecoration)> ClearDressing(WorldProject world,Building b){
  var cells=BuildingDesigner.Occupied(b).Select(i=>(X:b.X+i%(b.Width+1),Y:b.Y+i/(b.Width+1))).SelectMany(c=>new[]{(c.X,c.Y),(c.X-1,c.Y),(c.X,c.Y-1),(c.X-1,c.Y-1)}).ToHashSet();var removed=new List<(MapProject,WorldDecoration)>();
  foreach(var m in world.Maps){var p=m.Project;var ox=p.WorldX*256;var oy=p.WorldY*256;foreach(var d in p.Decorations.Where(d=>d.Id.StartsWith(DressingPrefix,StringComparison.Ordinal)&&d.Parts.Any(part=>cells.Contains((ox+d.X+part.Dx,oy+d.Y+part.Dy)))).ToList()){p.Decorations.Remove(d);removed.Add((p,d));}}
  return removed;
 }
 public static (int Added,int Skipped) ImportWorldBuildings(string json,WorldProject world,int seed,List<string> warnings,CancellationToken token=default){
  if(world.GeoReference is null)return(0,0);using var document=Parse(json);var features=ReadFeatures(document.RootElement,out _);var reference=world.GeoReference;var projection=new GeographicProjection(reference,reference.OriginCellX,reference.OriginCellY);var added=0;var skipped=0;var existing=world.Maps.SelectMany(m=>m.Project.Buildings).Concat(world.Buildings).Select(b=>b.SourceId).Where(s=>s is not null).ToHashSet();
  foreach(var feature in features.Where(f=>f.Polygon&&f.Tags.ContainsKey("building"))){
   token.ThrowIfCancellationRequested();var sourceId=feature.Tags.GetValueOrDefault("__pz_source");if(sourceId is not null&&existing.Contains(sourceId))continue;
   var rings=feature.Rings.Select(r=>r.Select(point=>{var p=projection.Project(point);return(X:p.X+reference.OriginCellX*256,Y:p.Y+reference.OriginCellY*256);}).ToList()).ToList();var ring=rings[0];var x=(int)Math.Floor(ring.Min(p=>p.X));var y=(int)Math.Floor(ring.Min(p=>p.Y));var width=Math.Max(BuildingDesigner.MinimumFootprint,(int)Math.Ceiling(ring.Max(p=>p.X)-x));var height=Math.Max(BuildingDesigner.MinimumFootprint,(int)Math.Ceiling(ring.Max(p=>p.Y)-y));if(width>64||height>64)continue;
   // shared when the footprint or the free line a section keeps around a building (MapGenerator.CanPlace) reaches another section;
   // a section rejects such an outline as outside its map, so it would be lost at the seam
   var owners=new[]{x-1,x,x+width}.SelectMany(cx=>new[]{y-1,y,y+height}.Select(cy=>WorldAssembler.MemberAt(world,cx,cy))).ToArray();if(new[]{owners[4],owners[5],owners[7],owners[8]}.Any(m=>m is null)||owners.Where(m=>m is not null).Select(m=>m!.Id).Distinct().Count()<2)continue;
   var tags=feature.Tags;var sourceKind=tags.GetValueOrDefault("building","yes");var kind=KindFromTag(tags)??(tags.ContainsKey("shop")?"shop":sourceKind switch{"retail" or "commercial" or "train_station"=>"shop","apartments" or "residential"=>"apartments","school" or "college" or "kindergarten"=>"school","hospital"=>"clinic","hotel"=>"hotel","industrial"=>"industrial","warehouse" or "shed" or "service"=>"warehouse","garages" or "garage"=>"garage",_=>"house"});
   string? Tag(string name)=>tags.TryGetValue(name,out var value)?value[..Math.Min(100,value.Length)]:null;
   var b=new Building{X=x,Y=y,Width=width,Height=height,Kind=kind,Name=Tag("name")??BuildingDesigner.Names[kind],SourceId=sourceId,SourceKind=sourceKind,SourceLevels=Tag("building:levels"),SourceBasements=Tag("building:levels:underground"),SourceRoof=Tag("roof:shape")};var levels=kind is "apartments" or "school" or "clinic" or "hotel"?2:1;
   if(int.TryParse(b.SourceLevels,out var specified)&&specified>0){levels=Math.Clamp(specified,1,ZLevels.AboveGroundCount);b.LevelsOrigin="osm-levels";}else if(tags.TryGetValue("height",out var h)&&double.TryParse(h.Replace(" m",""),NumberStyles.Float,CultureInfo.InvariantCulture,out var metres)&&double.IsFinite(metres)&&metres>0){levels=Math.Clamp((int)Math.Min(ZLevels.AboveGroundCount,Math.Round(metres/3)),1,ZLevels.AboveGroundCount);b.LevelsOrigin="osm-height";}
   var basements=int.TryParse(b.SourceBasements,out var depth)?Math.Clamp(depth,0,ZLevels.BasementCount):0;if(levels+basements>1&&!BuildingDesigner.HoldsStairs(width,height)){levels=1;basements=0;warnings.Add($"Shared building {b.Name} is under 6 tiles on both sides and keeps one floor; original source tags were preserved.");}
   List<(MapProject,WorldDecoration)> cleared=[];try{b.Design=BuildingDesigner.Generate(b,levels,unchecked(seed^x*73856093^y*19349663),"rect",basements);if(b.SourceRoof is "flat" or "gabled" or "shed" or "hipped")b.Design.Roof=b.SourceRoof;else if(b.SourceRoof=="skillion")b.Design.Roof="shed";if(RoofGeometry.SelectSafeAutomaticRoof(b))warnings.Add($"Roof for shared building {b.Name} was adapted to fit z={ZLevels.Max}; original source tags were preserved.");if(specified>ZLevels.AboveGroundCount||depth>ZLevels.BasementCount)warnings.Add($"Source floor counts for shared building {b.Name} were limited to 32 above-ground and 32 basement levels.");if(!ImportedBuildingGeometry.Apply(b,rings,out var footprintReason))throw new ArgumentException(footprintReason);b.SourceOutline=ImportedBuildingGeometry.Capture(feature.Rings,out var simplified);b.SourceOutlineSimplified=simplified;ApplyAppearanceTags(b,tags,null,problem=>warnings.Add($"Shared building {b.Name}: appearance tag ignored: {problem}."));ApplyRoomTags(b,tags,problem=>warnings.Add($"Shared building {b.Name}: room tag ignored: {problem}."));cleared=ClearDressing(world,b);world.Buildings.Add(b);WorldAssembler.Validate(world);added++;if(sourceId is not null)existing.Add(sourceId);}catch(ArgumentException){world.Buildings.Remove(b);foreach(var (owner,d) in cleared)owner.Decorations.Add(d);skipped++;}
  }
  if(added>0)warnings.Add($"Shared buildings spanning section boundaries restored from complete OSM outlines: {added}. Each is stored once in the world; rooms and tiles are clipped to native cells.");if(skipped>0)warnings.Add($"Shared buildings skipped because of water, overlaps, or inaccessible layouts: {skipped}.");return(added,skipped);
 }
}
